// w7-report-format: operator-friendly ops digest for Telegram
const r = $input.item.json;
const lines = [];

function humanTime(isoStr) {
  if (!isoStr) return 'unknown';
  try {
    const dt = new Date(isoStr);
    const diffMs = Date.now() - dt.getTime();
    const diffMins = Math.floor(diffMs / 60000);
    if (diffMins < 60) return diffMins + 'm ago';
    const diffHours = Math.floor(diffMins / 60);
    if (diffHours < 24) return diffHours + 'h ago';
    const diffDays = Math.floor(diffHours / 24);
    if (diffDays < 7) return diffDays + 'd ago';
    return dt.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
  } catch (e) { return isoStr || 'unknown'; }
}

function workerStep(step) {
  const map = {
    pre_flight: 'starting up',
    opening_pr: 'opening a PR',
    awaiting_bugbot: 'waiting for code review bot',
    post_merge_cleanup: 'cleaning up after merge',
    running_pre_commit: 'running checks',
    writing_tests: 'writing tests',
  };
  return map[step] || step || '?';
}

function budgetText(budget) {
  if (!budget) return 'No budget data';
  // Handle {state:...} format (future)
  if (!Array.isArray(budget) && budget.state) {
    const s = budget.state;
    if (s === 'safe')  return 'Safe \u2014 no limits hit';
    if (s === 'watch') return 'Watch \u2014 approaching limit \u26a0\ufe0f';
    if (s === 'limit') return 'At limit \u2014 new work needs approval \u274c';
  }
  // Handle legacy array-of-providers format
  const providers = Array.isArray(budget) ? budget : [];
  if (providers.length === 0) return 'No budget data';
  const pcts = providers.filter(function(p) { return p.remaining_percent != null; }).map(function(p) { return Number(p.remaining_percent); });
  const minPct = pcts.length > 0 ? Math.min.apply(null, pcts) : 100;
  const detail = providers.map(function(p) { return (p.provider || '?') + ' ' + (p.remaining_percent != null ? p.remaining_percent + '% left' : 'unknown'); }).join(' \u00b7 ');
  if (minPct >= 50) return 'Safe \u2014 ' + detail;
  if (minPct >= 20) return 'Watch \u26a0\ufe0f \u2014 ' + detail;
  return 'At limit \u274c \u2014 ' + detail;
}

const ts = humanTime(r.generated_at);
lines.push('\uD83D\uDEE0 *Miru Status* \u2014 ' + ts);
lines.push('');

const completions = (r.last_completions || []).filter(function (c) {
  return !/^TEST-/.test(c.ticket_id || '');
});
const shipped = completions.filter(function (c) { return c.status === 'CONFIRMED_WORKING'; }).slice(-5);
const failed  = completions.filter(function (c) { return c.status === 'FAILED'; }).slice(-3);
const partial = completions.filter(function (c) { return c.status === 'INCONCLUSIVE'; }).slice(-3);

if (shipped.length > 0) {
  lines.push('*What shipped*');
  shipped.forEach(function (c) {
    var s = (c.summary || '(no description)').substring(0, 120) + ((c.summary || '').length > 120 ? '...' : '');
    lines.push('\u2705 *' + (c.ticket_id || '?') + '* \u2014 ' + s);
  });
  lines.push('');
}

if (failed.length > 0) {
  lines.push('*What failed*');
  failed.forEach(function (c) {
    var s = (c.summary || '(no description)').substring(0, 120) + ((c.summary || '').length > 120 ? '...' : '');
    lines.push('\u274c *' + (c.ticket_id || '?') + '* \u2014 ' + s);
  });
  lines.push('');
}

if (partial.length > 0) {
  lines.push('*Needs attention*');
  partial.forEach(function (c) {
    var s = (c.summary || '(no description)').substring(0, 120) + ((c.summary || '').length > 120 ? '...' : '');
    lines.push('\u26a0\ufe0f *' + (c.ticket_id || '?') + '* \u2014 ' + s);
  });
  lines.push('');
}

if (shipped.length === 0 && failed.length === 0 && partial.length === 0) {
  lines.push('_No recent real activity_');
  lines.push('');
}

const dlq = r.dlq_count != null ? Number(r.dlq_count) : 0;
if (dlq > 20) {
  lines.push('*Failed dispatch queue:* ' + dlq + ' attempts \u26a0\ufe0f \u2014 this is high, worth reviewing');
} else if (dlq > 0) {
  lines.push('*Failed dispatch queue:* ' + dlq + ' attempts');
} else {
  lines.push('*Failed dispatch queue:* Clear');
}
lines.push('');

lines.push('*Budget:* ' + budgetText(r.budget));
lines.push('');

const cutoff = new Date(Date.now() - 15 * 60 * 1000);
const active = (r.last_heartbeats || []).filter(function (h) {
  try { return new Date(h.ts) > cutoff; } catch (e) { return false; }
});

if (active.length > 0) {
  lines.push('*Active workers*');
  active.forEach(function (h) {
    lines.push(
      '\uD83D\uDD04 ' + (h.worker_id || '?') +
      ' \u2014 working on *' + (h.ticket_id || '?') + '*' +
      ' (' + workerStep(h.step) + ', last seen ' + humanTime(h.ts) + ')'
    );
  });
} else {
  lines.push('*Active workers:* None right now');
}

return { json: { text: lines.join('\n') } };

